    11	public class MessageService {
    12	    private final MessageRepository messageRepository;
    13	    private final MessageProcessor messageProcessor;
    14	
    15	    public MessageService(MessageRepository messageRepository, MessageProcessor messageProcessor) {
    16	        this.messageRepository = messageRepository;
    17	        this.messageProcessor = messageProcessor;
    18	    }
    19	
    20	    public void send(MessageChannel channel, String to, String subject, String body) {
    21	        MessageRuleContext context = new MessageRuleContext(channel, to, subject, body);
    22	        messageProcessor.process(context);
    23	
    24	        Message message = new Message(
    25	                messageRepository.nextId(),
    26	                context.getChannel(),
    27	                context.getTo(),
    28	                context.getSubject(),
    29	                context.getBody(),
    30	                context.getStatus()
    31	        );
    32	        messageRepository.save(message);
    33	
    34	        for (MessageRuleContext.AdditionalMessage additional : context.getAdditionalMessages()) {
    35	            Message additionalMsg = new Message(
    36	                    messageRepository.nextId(),
    37	                    channel,
    38	                    additional.getTo(),
    39	                    additional.getSubject(),
    40	                    additional.getBody(),
    41	                    context.getStatus()
    42	            );
    43	            messageRepository.save(additionalMsg);
    44	        }
    45	    }
    46	
    47	    public List<Message> getAllMessages() {
    48	        return messageRepository.findAll();
    49	    }
    50	}
