     7	public class EmailValidationRule implements MessageRule {
     8	
     9	    @Override
    10	    public void apply(MessageRuleContext context) {
    11	        if (!isValidEmail(context.getTo())) {
    12	            context.setStatus(MessageStatus.BLOCKED);
    13	        }
    14	    }
    15	
    16	    private boolean isValidEmail(String email) {
    17	        if (email == null || email.isBlank()) {
    18	            return false;
    19	        }
    20	
    21	        long atCount = email.chars().filter(ch -> ch == '@').count();
    22	        if (atCount != 1) {
    23	            return false;
    24	        }
    25	
    26	        int atIndex = email.indexOf('@');
    27	        if (atIndex == 0 || atIndex == email.length() - 1) {
    28	            return false;
    29	        }
    30	
    31	        String domain = email.substring(atIndex + 1);
    32	        return domain.contains(".");
    33	    }
    34	}
