 16	public class ReservationService {
 17	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 18	
 19	    private final ReservationRepository reservationRepository;
 20	    private final RoomRepository roomRepository;
 21	    private final PricingService pricingService;
 22	    private final MessageService messageService;
 23	
 24	    public ReservationService(ReservationRepository reservationRepository,
 25	                            RoomRepository roomRepository,
 26	                            PricingService pricingService,
 27	                            MessageService messageService) {
 28	        this.reservationRepository = reservationRepository;
 29	        this.roomRepository = roomRepository;
 30	        this.pricingService = pricingService;
 31	        this.messageService = messageService;
