 91	
 92	        reservation.setStatus(ReservationStatus.CONFIRMED);
 93	        reservation.setAmountPaid(reservation.getTotal());
 94	
 95	        sendConfirmationEmail(reservation);
 96	
 97	        return reservationRepository.save(reservation);
 98	    }
