159	    private void sendConfirmationEmail(Reservation reservation) {
160	        String subject = "Reserva confirmada - Pousada Maré Alta";
161	        String document = formatDocumentText(reservation);
162	
163	        String body = String.format(
164	                "Olá, %s!\n\n" +
165	                "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
166	                "%s\n\n" +
167	                "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
168	                "Até breve!",
169	                reservation.getGuestName(),
170	                document
171	        );
172	
173	        messageService.send(MessageChannel.EMAIL, reservation.getGuestEmail(), subject, body);
174	    }
175	
176	    private Map<String, Object> generateDocument(Reservation reservation) {
177	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
178	                .orElseThrow(() -> new RoomNotFoundException());
179	
180	        Map<String, Object> document = new HashMap<>();
181	        document.put("title", "Comprovante de reserva");
182	        document.put("reservationId", reservation.getId());
183	        document.put("guestName", reservation.getGuestName());
184	        document.put("guestCpf", reservation.getGuestCpf());
185	        document.put("roomNumber", reservation.getRoomNumber());
186	        document.put("roomType", room.getType().name());
187	        document.put("checkIn", reservation.getCheckIn());
188	        document.put("checkOut", reservation.getCheckOut());
189	        document.put("nights", reservation.getNights());
190	        document.put("subtotal", reservation.getSubtotal());
191	        document.put("discount", reservation.getDiscount());
192	        document.put("total", reservation.getTotal());
193	
194	        return document;
195	    }
196	
197	    private String formatDocumentText(Reservation reservation) {
198	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
199	                .orElseThrow(() -> new RoomNotFoundException());
200	
201	        StringBuilder sb = new StringBuilder();
202	        sb.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
203	        sb.append(String.format("Hóspede: %s (CPF %s)\n", reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
204	        sb.append(String.format("Quarto: %s (%s)\n", reservation.getRoomNumber(), room.getType().name()));
205	        sb.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
206	                reservation.getCheckIn().format(DATE_FORMATTER),
207	                reservation.getCheckOut().format(DATE_FORMATTER),
208	                reservation.getNights(),
209	                reservation.getNights() == 1 ? "diária" : "diárias"));
210	        sb.append(String.format("Diárias: %s\n", formatMoney(reservation.getSubtotal())));
211	
212	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
213	            sb.append(String.format("Desconto: %s\n", formatMoney(reservation.getDiscount())));
214	        }
215	
216	        sb.append(String.format("Total: %s", formatMoney(reservation.getTotal())));
217	
218	        return sb.toString();
219	    }
220	
221	    private String formatCpf(String cpf) {
222	        if (cpf.length() == 11) {
223	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
224	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
225	        }
226	        return cpf;
227	    }
228	
229	    private String formatMoney(BigDecimal amount) {
230	        return String.format("R$ %,.2f", amount).replace(",", "X").replace(".", ",").replace("X", ".");
231	    }
232	
233	    public static class RoomNotFoundException extends RuntimeException {}
234	    public static class ReservationNotFoundException extends RuntimeException {}
235	    public static class InvalidRequestException extends RuntimeException {
236	        public InvalidRequestException(String message) {
237	            super(message);
238	        }
239	    }
240	    public static class CapacityExceededException extends RuntimeException {}
241	    public static class RoomUnavailableException extends RuntimeException {}
242	    public static class OperationNotAllowedException extends RuntimeException {}
243	}
