249	import java.math.BigDecimal;
250	import java.math.RoundingMode;
251	import java.time.LocalDate;
252	import java.time.Month;
253	
254	public class PricingService {
255	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
256	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
257	
258	    public BigDecimal calculateNightPrice(Room room, LocalDate night) {
259	        BigDecimal baseRate = room.getNightlyRate();
260	        if (isHighSeason(night)) {
261	            return round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
262	        }
263	        return baseRate;
264	    }
265	
266	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
267	        BigDecimal total = BigDecimal.ZERO;
268	        LocalDate night = checkIn;
269	        while (night.isBefore(checkOut)) {
270	            total = total.add(calculateNightPrice(room, night));
271	            night = night.plusDays(1);
272	        }
273	        return round(total);
274	    }
275	
276	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
277	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
278	            return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE));
279	        }
280	        return BigDecimal.ZERO;
281	    }
282	
283	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
284	        return round(subtotal.subtract(discount));
285	    }
286	
287	    private boolean isHighSeason(LocalDate date) {
288	        Month month = date.getMonth();
289	        int day = date.getDayOfMonth();
290	
291	        if (month == Month.DECEMBER && day >= 15) {
292	            return true;
293	        }
294	
295	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
296	            return true;
297	        }
298	
299	        return month == Month.JULY;
300	    }
301	
302	    private BigDecimal round(BigDecimal value) {
303	        return value.setScale(2, RoundingMode.HALF_EVEN);
304	    }
305	}
