371	                        reservation.getRoomNumber(),
372	                        reservation.getCheckIn().format(DATE_FORMATTER),
373	                        reservation.getCheckOut().format(DATE_FORMATTER),
374	                        reservation.getStatus().name(),
375	                        formatAmount(revenue)));
376	
377	                totalRevenue = totalRevenue.add(revenue);
378	            }
379	        }
380	
381	        csv.append(String.format("total,%s", formatAmount(totalRevenue)));
382	
383	        return csv.toString();
384	    }
