 34	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
 35	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
 36	                                        int guests, RatePlan ratePlan) {
 37	        Room room = roomRepository.findByNumber(roomNumber)
 38	                .orElseThrow(() -> new RoomNotFoundException());
 39	
 40	        if (guests < 1) {
 41	            throw new InvalidRequestException("Número de hóspedes deve ser no mínimo 1");
 42	        }
 43	
 44	        if (guests > room.getCapacity()) {
 45	            throw new CapacityExceededException();
 46	        }
 47	
 48	        if (!checkOut.isAfter(checkIn)) {
 49	            throw new InvalidRequestException("Data de saída deve ser após a data de entrada");
 50	        }
 51	
 52	        LocalDate night = checkIn;
 53	        while (night.isBefore(checkOut)) {
 54	            List<Reservation> existing = reservationRepository.findByRoomAndNight(roomNumber, night);
 55	            if (!existing.isEmpty()) {
 56	                throw new RoomUnavailableException();
 57	            }
 58	            night = night.plusDays(1);
 59	        }
 60	
 61	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
 62	        BigDecimal subtotal = pricingService.calculateSubtotal(room, checkIn, checkOut);
 63	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
 64	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
 65	
