 26	    public List<Reservation> findByRoomAndNight(String roomNumber, LocalDate night) {
 27	        return reservations.values().stream()
 28	                .filter(r -> r.getRoomNumber().equals(roomNumber))
 29	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
 30	                .filter(r -> r.occupiesNight(night))
 31	                .collect(Collectors.toList());
 32	    }
 33	
 34	    public List<Reservation> findPaidReservationsForNight(LocalDate night) {
 35	        return reservations.values().stream()
 36	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
 37	                .filter(r -> r.isPaid())
 38	                .filter(r -> r.occupiesNight(night))
 39	                .sorted(Comparator.comparing(Reservation::getRoomNumber))
 40	                .collect(Collectors.toList());
 41	    }
 42	
 43	    public List<Reservation> findReservationsStartingInMonth(YearMonth month) {
 44	        return reservations.values().stream()
 45	                .filter(r -> {
 46	                    YearMonth checkInMonth = YearMonth.from(r.getCheckIn());
 47	                    return checkInMonth.equals(month);
 48	                })
 49	                .filter(r -> r.getAmountPaid().compareTo(r.getRefund() != null ? r.getRefund() : r.getAmountPaid().multiply(BigDecimal.ZERO)) > 0)
 50	                .sorted(Comparator.comparing(Reservation::getCheckIn).thenComparing(Reservation::getId))
 51	                .collect(Collectors.toList());
 52	    }
 53	
 54	    public long nextId() {
 55	        return nextId.getAndIncrement();
 56	    }
