236	
237	    public boolean occupiesNight(LocalDate night) {
238	        return !night.isBefore(checkIn) && night.isBefore(checkOut);
239	    }
240	
241	    public boolean canConfirm() {
242	        return status == ReservationStatus.PENDING;
243	    }
244	
245	    public boolean canCheckIn() {
246	        return status == ReservationStatus.CONFIRMED;
247	    }
248	
249	    public boolean canCheckOut() {
250	        return status == ReservationStatus.CHECKED_IN;
251	    }
252	
253	    public boolean canCancel() {
254	        return status == ReservationStatus.PENDING || status == ReservationStatus.CONFIRMED;
255	    }
256	
257	    public boolean isPaid() {
258	        return status == ReservationStatus.CONFIRMED
259	            || status == ReservationStatus.CHECKED_IN
260	            || status == ReservationStatus.CHECKED_OUT;
261	    }
